const dictionaries: Record<Locale, Record<TranslationKey, string>> = { "pt-BR": ptBR, en, es, de, fr };
const storageKey = "okami-sentinel.locale";
let activeLocale: Locale = "pt-BR";

export function resolveLocale(value: string | null | undefined): Locale {
  const normalized = value?.toLowerCase() ?? "";
  if (normalized.startsWith("pt")) return "pt-BR";
  if (normalized.startsWith("es")) return "es";
  if (normalized.startsWith("de")) return "de";
  if (normalized.startsWith("fr")) return "fr";
  if (normalized.startsWith("en")) return "en";
  return "pt-BR";
}

export function getIntlLocale(): Locale { return activeLocale; }

export function translate(locale: Locale, key: TranslationKey, variables: Record<string, string | number> = {}): string {
  return dictionaries[locale][key].replace(/\{(\w+)\}/g, (_, name: string) => String(variables[name] ?? `{${name}}`));
}

type I18nValue = {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: TranslationKey, variables?: Record<string, string | number>) => string;
};

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(() => {
    if (typeof window === "undefined") return "pt-BR";
    return resolveLocale(window.localStorage.getItem(storageKey) ?? window.navigator.language);
  });
  activeLocale = locale;
  useEffect(() => {
    activeLocale = locale;
    document.documentElement.lang = locale;
    window.localStorage.setItem(storageKey, locale);
  }, [locale]);
  const setLocale = useCallback((next: Locale) => setLocaleState(next), []);
  const t = useCallback((key: TranslationKey, variables?: Record<string, string | number>) => translate(locale, key, variables), [locale]);
  const value = useMemo(() => ({ locale, setLocale, t }), [locale, setLocale, t]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const value = useContext(I18nContext);
  if (!value) throw new Error("useI18n must be used inside I18nProvider");
  return value;
}
